            goal: "input: n · แสดง <b>จำนวนเฉพาะที่ไม่เกิน n: c ตัว</b> และ <b>n เป็นจำนวนเฉพาะ: 1/0</b> (main เขียนไว้แล้ว)",
            starter: "#include <stdio.h>\n\nint isPrime(int n) {\n    /* คืน 1 ถ้า n เป็นจำนวนเฉพาะ ไม่เช่นนั้นคืน 0 */\n    return 0;\n}\n\nint main(void) {\n    int n = 0;\n    scanf(\"%d\", &n);\n    int count = 0;\n    for (int i = 2; i <= n; i++) {\n        if (isPrime(i)) {\n            count++;\n        }\n    }\n    printf(\"จำนวนเฉพาะที่ไม่เกิน %d: %d ตัว\\n\", n, count);\n    printf(\"%d เป็นจำนวนเฉพาะ: %d\\n\", n, isPrime(n));\n    return 0;\n}\n", xp: 60,
