            starter: "#include <stdio.h>\n#include <ctype.h>\n#include <stddef.h>\n\nsize_t myStrlen(const char *s) {\n    /* เดินพอยน์เตอร์จนเจอ '\\0' */\n    return 0;\n}\n\nvoid toUpperInPlace(char *s) {\n    /* แก้ทุกตัวอักษรเป็นตัวพิมพ์ใหญ่ */\n}\n\nint main(void) {\n    char w[64] = \"\";\n    scanf(\"%63s\", w);\n    printf(\"ความยาว: %zu\\n\", myStrlen(w));\n    toUpperInPlace(w);\n    printf(\"ตัวพิมพ์ใหญ่: %s\\n\", w);\n    return 0;\n}\n", xp: 50,
