            starter: "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char text[128] = \"\", key[16] = \"\";\n    if (fgets(text, sizeof text, stdin) == NULL) {\n        text[0] = '\\0';\n    }\n    text[strcspn(text, \"\\n\")] = '\\0';\n    if (fgets(key, sizeof key, stdin) == NULL) {\n        key[0] = '\\0';\n    }\n    char c = key[0];\n    /* strchr แล้วคำนวณตำแหน่ง */\n    return 0;\n}\n", xp: 60,
