            starter: "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n    char name[32];\n    long long sum;\n} Category;\n\nint main(void) {\n    char cmd[16], cat[32], amount[32];\n    /* while (scanf(\"%15s\", cmd) == 1) { … } */\n    return 0;\n}\n", xp: 90,
