            starter: "#include <stdio.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Entry {\n    char *key;\n    char *value;\n    struct Entry *next;\n} Entry;\n\ntypedef struct {\n    Entry **buckets;\n    size_t nbuckets;\n    size_t count;\n} Table;\n\nint main(void) {\n    char cmd[16], k[64], v[64];\n    /* สร้างตาราง 4 บัคเก็ต (calloc) แล้วรับคำสั่ง · จบแล้วคืนทุกโหนด สตริง และอาร์เรย์บัคเก็ต */\n    return 0;\n}\n", xp: 110,
