            starter: "#include <stdio.h>\n\nstatic int counter = 0;\n\nstatic int next(void) {\n    return ++counter;\n}\n\nint main(void) {\n    printf(\"%d %d\\n\", next(), next());\n    printf(\"%d %d\\n\", next(), next());\n    return 0;\n}\n", xp: 40,
